import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define custom CUDA kernels for ReLU and Sigmoid
custom_ops_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

__global__ void relu_kernel(const float* __restrict__ input, float* __restrict__ output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size){
        float val = input[idx];
        output[idx] = val > 0 ? val : 0;
    }
}

__global__ void sigmoid_kernel(const float* __restrict__ input, float* __restrict__ output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size){
        output[idx] = 1.0f / (1.0f + expf(-input[idx]));
    }
}

torch::Tensor custom_relu_cuda(torch::Tensor input){
    auto out = torch::zeros_like(input);
    int size = input.numel();
    int threads = 256;
    int blocks = (size + threads - 1) / threads;
    relu_kernel<<<blocks, threads>>>(input.data_ptr<float>(), out.data_ptr<float>(), size);
    return out;
}

torch::Tensor custom_sigmoid_cuda(torch::Tensor input){
    auto out = torch::zeros_like(input);
    int size = input.numel();
    int threads = 256;
    int blocks = (size + threads - 1) / threads;
    sigmoid_kernel<<<blocks, threads>>>(input.data_ptr<float>(), out.data_ptr<float>(), size);
    return out;
}
"""

custom_ops_cpp_source = r"""
torch::Tensor custom_relu_cuda(torch::Tensor input);
torch::Tensor custom_sigmoid_cuda(torch::Tensor input);
"""

# Compile the custom CUDA operators
custom_ops = load_inline(
    name="custom_ops",
    cpp_sources=custom_ops_cpp_source,
    cuda_sources=custom_ops_source,
    functions=["custom_relu_cuda", "custom_sigmoid_cuda"],
    verbose=False,
)

# Define PyTorch modules that wrap the custom CUDA kernels
class CustomReLU(nn.Module):
    def forward(self, input: torch.Tensor) -> torch.Tensor:
        return custom_ops.custom_relu_cuda(input)

class CustomSigmoid(nn.Module):
    def forward(self, input: torch.Tensor) -> torch.Tensor:
        return custom_ops.custom_sigmoid_cuda(input)

class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        """
        EfficientNetB2 architecture with custom CUDA operators.
        """
        super(ModelNew, self).__init__()

        # Replace ReLU and Sigmoid with custom modules
        self.CustomReLU = CustomReLU()
        self.CustomSigmoid = CustomSigmoid()

        self.conv1 = nn.Conv2d(3, 32, kernel_size=3, stride=2, padding=1, bias=False)
        self.bn1 = nn.BatchNorm2d(32)

        # MBConv blocks
        self.mbconv1 = self._make_mbconv_block(32, 96, 1, 3)
        self.mbconv2 = self._make_mbconv_block(96, 144, 2, 6)
        self.mbconv3 = self._make_mbconv_block(144, 192, 2, 6)
        self.mbconv4 = self._make_mbconv_block(192, 288, 2, 6)
        self.mbconv5 = self._make_mbconv_block(288, 384, 1, 6)

        # Final layers
        self.conv_final = nn.Conv2d(384, 1408, kernel_size=1, stride=1, padding=0, bias=False)
        self.bn_final = nn.BatchNorm2d(1408)
        self.avgpool = nn.AdaptiveAvgPool2d((1, 1))
        self.fc = nn.Linear(1408, num_classes)

    def _make_mbconv_block(self, in_channels, out_channels, stride, expand_ratio):
        """
        Helper function to create an MBConv block with custom ReLU/Sigmoid.
        """
        layers = []
        expanded_channels = in_channels * expand_ratio

        # Expansion phase
        if expand_ratio != 1:
            layers.append(nn.Conv2d(in_channels, expanded_channels, kernel_size=1, stride=1, padding=0, bias=False))
            layers.append(nn.BatchNorm2d(expanded_channels))
            # Custom ReLU
            layers.append(CustomReLU())

        # Depthwise convolution
        layers.append(nn.Conv2d(expanded_channels, expanded_channels, kernel_size=3, stride=stride, padding=1,
                                groups=expanded_channels, bias=False))
        layers.append(nn.BatchNorm2d(expanded_channels))
        layers.append(CustomReLU())

        # Squeeze and Excitation
        layers.append(nn.AdaptiveAvgPool2d((1, 1)))
        layers.append(nn.Conv2d(expanded_channels, expanded_channels // 4, kernel_size=1, stride=1, padding=0, bias=False))
        layers.append(CustomReLU())
        layers.append(nn.Conv2d(expanded_channels // 4, expanded_channels, kernel_size=1, stride=1, padding=0, bias=False))
        # Custom Sigmoid
        layers.append(CustomSigmoid())

        # Output phase
        layers.append(nn.Conv2d(expanded_channels, out_channels, kernel_size=1, stride=1, padding=0, bias=False))
        layers.append(nn.BatchNorm2d(out_channels))

        return nn.Sequential(*layers)

    def forward(self, x):
        x = self.bn1(self.conv1(x))
        x = self.CustomReLU(x)

        x = self.mbconv1(x)
        x = self.mbconv2(x)
        x = self.mbconv3(x)
        x = self.mbconv4(x)
        x = self.mbconv5(x)

        x = self.bn_final(self.conv_final(x))
        x = self.CustomReLU(x)

        x = self.avgpool(x)
        x = torch.flatten(x, 1)
        x = self.fc(x)
        return x

